#include <iostream>
#include <cmath>
using namespace std;

void hanoi(int n, char source, char target, char auxiliary) {
    if (n == 1) {
        cout << "移动盘子 1 从 " << source << " 到 " << target << endl;
        return;
    }

    hanoi(n - 1, source, auxiliary, target);
    cout << "移动盘子 " << n << " 从 " << source << " 到 " << target << endl;
    hanoi(n - 1, auxiliary, target, source);
}

int countMoves(int n) {
    return pow(2, n) - 1;
}

int main() {
    int n = 3;

    cout << "汉诺塔问题: " << n << " 个盘子" << endl;
    cout << "需要移动 " << countMoves(n) << " 次" << endl;
    cout << "
移动步骤:" << endl;

    hanoi(n, 'A', 'C', 'B');

    return 0;
}
